# ----------------------------- BASIC HELPERS -----------------------------

def pause():
    input("\nEnter दबाएँ...")


def norm(text):
    return " ".join(str(text).lower().strip().split())


def clear_line():
    print("-" * 64)


def get_api_key():
    """Read Gemini key from environment first, then from a local key file."""
    key = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")
    if key:
        return key.strip()
    try:
        if os.path.exists(GEMINI_KEY_FILE):
            with open(GEMINI_KEY_FILE, "r", encoding="utf-8") as f:
                key = f.read().strip()
                if key:
                    return key
    except Exception:
        return None
    return None


def save_api_key(key):
    key = str(key).strip()
    if not key:
        return False
    try:
        with open(GEMINI_KEY_FILE, "w", encoding="utf-8") as f:
            f.write(key)
        return True
    except Exception as exc:
        print("API key save error:", exc)
        return False


def setup_gemini_key():
    print("\n=== 🌐 GEMINI ONLINE MODE SETUP ===")
    print("Google AI Studio से अपनी Gemini API key लेकर नीचे paste करो।")
    print("Key स्क्रीन पर दिखाई दे सकती है; इसे किसी और को share मत करना।")
    key = input("Gemini API key: ").strip()
    if save_api_key(key):
        print("✅ API key स्थानीय रूप से सहेज दी गई।")
        return True
    print("❌ API key सहेजी नहीं जा सकी।")
    return False


def make_gemini_client():
    if genai is None:
        return None
    key = get_api_key()
    if not key:
        return None
    try:
        return genai.Client(api_key=key)
    except Exception as exc:
        print("[Gemini client error]", str(exc)[:120])
        return None


def speak(text):
    """Speak text using the Android/Pydroid routes that are available.
    Returns True only when a TTS route actually accepts the request.
    """
    spoken = str(text).strip()
    if not spoken:
        return False

    # 1) Pydroid/SL4A Android bridge, when installed.
    if ANDROID_DROID is not None:
        try:
            result = ANDROID_DROID.ttsSpeak(spoken)
            # ttsSpeak normally returns immediately; reaching here means the call was accepted.
            return True
        except Exception:
            pass

    # 2) Plyer Android TTS route.
    if plyer_tts is not None:
        try:
            plyer_tts.speak(message=spoken)
            return True
        except Exception:
            pass

    # 3) PyJNIus route. This works in Android Python app environments that expose
    # an Activity; plain Pydroid terminal mode may not expose one.
    if autoclass is not None:
        try:
            TextToSpeech = autoclass("android.speech.tts.TextToSpeech")
            Locale = autoclass("java.util.Locale")
            try:
                Activity = autoclass("org.kivy.android.PythonActivity")
                activity = Activity.mActivity
            except Exception:
                Activity = autoclass("org.renpy.android.PythonActivity")
                activity = Activity.mActivity
            tts = TextToSpeech(activity, None)
            try:
                tts.setLanguage(Locale("hi", "IN"))
            except Exception:
                tts.setLanguage(Locale.US)
            status = tts.speak(spoken, TextToSpeech.QUEUE_FLUSH, None, "aryabhutt")
            if status != -1:
                return True
        except Exception:
            pass

    # 4) Desktop-style fallback. On many Android Pydroid setups this is unavailable,
    # so failure here is reported cleanly instead of pretending that speech worked.
    if pyttsx3 is not None:
        try:
            engine = pyttsx3.init()
            engine.say(spoken)
            engine.runAndWait()
            engine.stop()
            return True
        except Exception:
            pass

    return False


def voice_to_text():
    """Try Android speech recognition first, then SpeechRecognition."""
    if ANDROID_DROID is not None:
        try:
            result = ANDROID_DROID.recognizeSpeech(
                "आर्यभट्ट से प्रश्न पूछिए", "hi-IN", True
            )
            spoken = result.result if hasattr(result, "result") else result
            if spoken:
                spoken = str(spoken).strip()
                print("आपने कहा:", spoken)
                return spoken
        except Exception:
            print("", end="")

    if sr is not None:
        try:
            recognizer = sr.Recognizer()
            with sr.Microphone() as source:
                print("🎙️ बोलिए... मैं सुन रहा हूँ।")
                recognizer.adjust_for_ambient_noise(source, duration=0.4)
                audio = recognizer.listen(source, timeout=5, phrase_time_limit=10)
            spoken = recognizer.recognize_google(audio, language="hi-IN")
            print("आपने कहा:", spoken)
            return spoken
        except Exception as exc:
            print("[ध्वनि सुविधा] माइक्रोफोन से आवाज़ नहीं मिल सकी:", str(exc)[:100])
            return None

    print("[ध्वनि सुविधा] Android voice recognition उपलब्ध नहीं है; 'voice' लिखकर फिर कोशिश कर सकते हो।")
    return None


def load_json(path, default):
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        return default


def save_json(path, data):
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False, indent=2)
        return True
    except Exception as exc:
        print("सहेजने में समस्या:", exc)
        return False


def default_analytics():
    return {
        "schools": {},
        "students": 0,
        "sessions": 0,
        "games_played": 0,
        "riddles_solved": 0,
        "chat_questions": 0,
        "last_updated": None,
    }


def load_analytics():
    data = load_json(DATA_FILE, default_analytics())
    base = default_analytics()
    if not isinstance(data, dict):
        return base
    for key, value in base.items():
        data.setdefault(key, value)
    return data


def save_analytics(data):
    data["last_updated"] = datetime.now().isoformat(timespec="seconds")
    save_json(DATA_FILE, data)


def record_session():
    data = load_analytics()
    data["sessions"] = int(data.get("sessions", 0)) + 1
    save_analytics(data)


def record_chat_question():
    data = load_analytics()
    data["chat_questions"] = int(data.get("chat_questions", 0)) + 1
    save_analytics(data)


def record_game():
    data = load_analytics()
    data["games_played"] = int(data.get("games_played", 0)) + 1
    save_analytics(data)


def record_riddle():
    data = load_analytics()
    data["riddles_solved"] = int(data.get("riddles_solved", 0)) + 1
    save_analytics(data)


