def offline_answer(question):
    q = norm(question)

    # Direct keyword matching first.
    for keys, answer in OFFLINE_KNOWLEDGE:
        for key in keys:
            if norm(key) in q:
                return answer

    # Fuzzy matching for small typing mistakes.
    best_answer = None
    best_score = 0.0
    for keys, answer in OFFLINE_KNOWLEDGE:
        for key in keys:
            score = difflib.SequenceMatcher(None, q, norm(key)).ratio()
            if score > best_score:
                best_score = score
                best_answer = answer
    if best_score >= 0.52:
        return best_answer

    return (
        "आचार्य आर्यभट्ट: वत्स, इस प्रश्न का उत्तर मेरी ऑफलाइन ज्ञान-पुस्तिका में अभी नहीं है। "
        "तुम इसे थोड़ा सरल शब्दों में फिर पूछो, या ऑनलाइन Gemini मोड उपलब्ध हो तो उसे आज़माओ।"
    )


def gemini_answer(question, client):
    """Fast Gemini mode for exhibitions/demo use.

    At most two attempts are made. Each request has a short client timeout,
    so a temporary network problem quickly falls back to the offline book.
    """
    if client is None:
        return None

    prompt = (
        "तुम 'आचार्य आर्यभट्ट' शैली का Class 8 शैक्षिक सहायक हो। "
        "विद्यार्थी से सम्मानपूर्वक, सरल हिन्दी/हिंग्लिश में बात करो। "
        "उत्तर संक्षिप्त और सीधे दो; अनावश्यक अंग्रेज़ी या तकनीकी सिस्टम संदेश मत दो। "
        "जहाँ संभव हो 4-6 वाक्यों में समझाओ। ऐतिहासिक तथ्य गढ़ो मत।\n\n"
        "विद्यार्थी का प्रश्न: " + question
    )

    for attempt in range(1, GEMINI_MAX_ATTEMPTS + 1):
        try:
            response = client.models.generate_content(
                model=GEMINI_MODEL,
                contents=prompt,
                config={
                    "max_output_tokens": GEMINI_MAX_OUTPUT_TOKENS,
                    "http_options": {"timeout": GEMINI_TIMEOUT_MS},
                },
            )
            answer = getattr(response, "text", None)
            if answer and answer.strip():
                return answer.strip()

            if attempt < GEMINI_MAX_ATTEMPTS:
                print("[ऑनलाइन उत्तर खाली मिला — एक बार फिर कोशिश होगी]")

        except Exception as exc:
            if attempt < GEMINI_MAX_ATTEMPTS:
                print("[ऑनलाइन प्रयास 1 असफल — तुरंत दूसरी कोशिश]")
            else:
                print("[ऑनलाइन उत्तर जल्दी उपलब्ध नहीं हुआ — ऑफलाइन ज्ञान-पुस्तिका से उत्तर दिया जाएगा]")
                print("[तकनीकी कारण]", str(exc)[:120])

    return None


