    print("\n" + "=" * 64)
    print("💬 आचार्य आर्यभट्ट से ज्ञान-संवाद")
    print("=" * 64)
    print("आचार्य आर्यभट्ट:")
    print("आयुष्मान भव, प्रिय बालक!")
    print("मैं गणित, विज्ञान, खगोल, पढ़ाई और कोडिंग के प्रश्नों में सहायता कर सकता हूँ।")
    print("प्रश्न लिखो। 'वापस' लिखकर मुख्य मेनू में जाओ।")
    print("सिर्फ बोलकर पूछना हो तो 'voice' लिखो।")
    print("Gemini key सेट करनी हो तो 'api' लिखो।")

    if client is not None:
        print("🌐 ऑनलाइन ज्ञान-संवाद: सक्रिय")
    else:
        print("📚 ऑफलाइन ज्ञान-पुस्तिका: सक्रिय")
        print("ऑनलाइन Gemini के लिए 'api' लिखकर key सेट कर सकते हो।")

    while True:
        question = input("\nतुम: ").strip()

        if norm(question) in {"वापस", "back", "exit", "quit"}:
            print("आचार्य आर्यभट्ट: शुभं भवतु, वत्स!")
            return

        if norm(question) == "api":
            if setup_gemini_key():
                client = make_gemini_client()
                if client is not None:
                    print("🌐 ऑनलाइन Gemini अब सक्रिय है।")
                else:
                    print("❌ Key मिली, लेकिन Gemini client शुरू नहीं हो सका।")
            continue

        if norm(question) == "voice":
            spoken = voice_to_text()
            if spoken:
                question = spoken
            else:
                continue

        if not question:
            continue

        # Count each real question.
        data = load_analytics()
        data["chat_questions"] = int(data.get("chat_questions", 0)) + 1
        save_analytics(data)

        answer = gemini_answer(question, client)
        if answer:
            print("\n[ऑनलाइन ज्ञान-संवाद]")
        else:
            answer = offline_answer(question)
            print("\n[ऑफलाइन ज्ञान-पुस्तिका]")

        print("आचार्य आर्यभट्ट:", answer)

        # Optional spoken response.
        if norm(input("🔊 उत्तर आवाज़ में सुनना है? (हाँ/नहीं): ")) in {"हाँ", "ha", "yes", "y"}:
            if speak(answer):
                print("🔊 आचार्य आर्यभट्ट बोल रहे हैं...")
            else:
                print("🔇 इस Pydroid वातावरण में Android TTS/स्पीकर bridge उपलब्ध नहीं मिला। उत्तर ऊपर लिखा है।")
                print("   बाकी chatbot (online + offline) सामान्य रूप से चलता रहेगा।")


