def choose_riddle_batch():
    # Every visit shuffles the order, so the next visit does not simply repeat Q1-Q3.
    batch = RIDDLES[:]
    random.shuffle(batch)
    return batch


def treasure_hunt():
    print("\n" + "=" * 64)
    print("🧩 DIGITAL TREASURE HUNT — MISSION SAVE SIA")
    print("=" * 64)
    print("आचार्य आर्यभट्ट: आज तुम्हारे लिए 56 में से अलग-अलग पहेलियाँ आई हैं।")
    print("इस बार कितनी पहेलियाँ खेलनी हैं? 20 से 30 चुनो।")
    raw = input("संख्या (20-30, Enter = 20): ").strip()
    try:
        rounds = int(raw) if raw else 20
    except ValueError:
        rounds = 20
    rounds = max(20, min(30, rounds))

    riddles = choose_riddle_batch()
    score = 0

    for index in range(rounds):
        question, answers, display_answer = riddles[index % len(riddles)]
        print(f"\n🔐 पहेली {index + 1}/{rounds}")
        print(question)
        answer = norm(input("तुम्हारा उत्तर: "))

        if any(norm(a) == answer for a in answers):
            print("✓ आचार्य आर्यभट्ट: साधु! उत्तर सही है।")
            score += 1
            record_riddle()
        else:
            print("✗ सही उत्तर:", display_answer)

    print(f"\n🏆 पहेली परिणाम: {score}/{rounds}")
    if score == rounds:
        print("🎉 अद्भुत! सभी पहेलियाँ सही।")
        print("📚 ज्ञान-पुस्तक लिंक:", BOOK_LINK)
    else:
        print("आचार्य आर्यभट्ट: अभ्यास करते रहो, अगली बार और अच्छा होगा।")
    pause()


# ----------------------------- GAMES -----------------------------

def ask_rounds():
    raw = input("कितने rounds? 20-30 (Enter = 20): ").strip()
    try:
        value = int(raw) if raw else 20
    except ValueError:
        value = 20
    return max(20, min(30, value))


def guess_number():
    rounds = ask_rounds()
    score = 0
    print("\n🎯 Guess the Number — लगातार rounds")
    for r in range(1, rounds + 1):
        target = random.randint(1, 50)
        print(f"\nRound {r}/{rounds}: 1 से 50")
        for attempt in range(1, 6):
            try:
                guess = int(input(f"कोशिश {attempt}/5: "))
            except ValueError:
                print("संख्या लिखो।")
                continue
            if guess == target:
                print("🎉 सही!")
                score += 1
                break
            print("थोड़ा बड़ा!" if guess < target else "थोड़ा छोटा!")
        else:
            print("सही संख्या थी:", target)
    SCORES["Guess the Number"] = score
    print(f"\nFinal Score: {score}/{rounds}")
    record_game()


def flip_coin():
    rounds = ask_rounds()
    score = 0
    print("\n🪙 Flip a Coin — rounds")
    for r in range(1, rounds + 1):
        print(f"\nRound {r}/{rounds}")
        choice = norm(input("Heads या Tails? "))
        result = random.choice(["heads", "tails"])
        print("सिक्के का परिणाम:", "Heads" if result == "heads" else "Tails")
        if choice in {result, "heads" if result == "heads" else "tails"}:
            print("✓ सही अनुमान!")
            score += 1
        else:
            print("अगली बार प्रयास करो।")
    SCORES["Flip a Coin"] = score
    print(f"\nFinal Score: {score}/{rounds}")
    record_game()


def rps():
    rounds = ask_rounds()
    score = 0
    aliases = {
        "rock": "stone", "पत्थर": "stone", "पत्थर": "stone",
        "paper": "paper", "कागज": "paper",
        "scissors": "scissors", "कैंची": "scissors",
    }
    choices = ["stone", "paper", "scissors"]
    print("\n✊ Rock-Paper-Scissors — लगातार rounds")
    for r in range(1, rounds + 1):
        print(f"\nRound {r}/{rounds}")
        print("stone / paper / scissors")
        typed = norm(input("तुम: "))
        user = aliases.get(typed, typed)
        if user not in choices:
            print("गलत choice, यह round दोबारा नहीं गिना गया।")
            continue
        computer = random.choice(choices)
        print("Computer:", computer)
        if user == computer:
            print("Draw!")
        elif (user, computer) in {
            ("stone", "scissors"),
            ("scissors", "paper"),
            ("paper", "stone"),
        }:
            print("✓ तुम जीते!")
            score += 1
        else:
            print("Computer जीता।")
    SCORES["Rock-Paper-Scissors"] = score
    print(f"\nFinal Score: {score}/{rounds}")
    record_game()


