def word_scramble():
    word_bank = [
        "moon", "star", "earth", "sun", "math", "space", "planet",
        "school", "python", "science", "number", "circle", "square",
        "triangle", "rocket", "galaxy", "atom", "force", "energy",
        "coding", "orbit", "comet", "light", "water", "plant",
        "school", "teacher", "student", "zero", "prime",
    ]
    rounds = ask_rounds()
    score = 0
    print("\n🔤 Word Scramble — rounds")
    for r in range(1, rounds + 1):
        word = random.choice(word_bank)
        letters = list(word)
        random.shuffle(letters)
        scrambled = "".join(letters)
        print(f"\nRound {r}/{rounds}")
        print("Scrambled:", scrambled)
        if norm(input("Word: ")) == word:
            print("✓ Correct")
            score += 1
        else:
            print("सही शब्द:", word)
    SCORES["Word Scramble"] = score
    print(f"\nFinal Score: {score}/{rounds}")
    record_game()


