def daily_quiz():
    rounds = 20
    score = 0
    questions = DAILY_QUIZ * 2
    random.shuffle(questions)
    print("\n📚 DAILY QUIZ — 20 questions")
    for i, (question, options, correct) in enumerate(questions[:rounds], 1):
        print(f"\nQ{i}. {question}")
        for j, option in enumerate(options, 1):
            print(f"{j}. {option}")
        if input("उत्तर: ").strip() == correct:
            print("✓ सही")
            score += 1
        else:
            print("सही option:", correct)
    SCORES["Daily Quiz"] = score
    print(f"\nFinal Score: {score}/{rounds}")
    record_game()


