def load_timetable():
    default = {
        "सोमवार": ["", "", "", "", "", ""],
        "मंगलवार": ["", "", "", "", "", ""],
        "बुधवार": ["", "", "", "", "", ""],
        "गुरुवार": ["", "", "", "", "", ""],
        "शुक्रवार": ["", "", "", "", "", ""],
        "शनिवार": ["", "", "", "", "", ""],
    }
    data = load_json(TIMETABLE_FILE, default)
    if not isinstance(data, dict):
        return default
    for day in default:
        data.setdefault(day, ["", "", "", "", "", ""])
    return data


