def qr_scanner():
    print("\n📷 QR / URL SCANNER")
    print("1. कैमरे से QR scan करने की कोशिश")
    print("2. URL/text manually जाँचें")
    print("0. वापस")
    choice = input("चुनें: ").strip()

    if choice == "0":
        return

    if choice == "2":
        value = input("URL या text: ").strip()
        if value.startswith(("http://", "https://")):
            print("✓ यह URL जैसा दिखता है:", value)
        elif value:
            print("✓ Text मिला:", value)
        else:
            print("कुछ दर्ज नहीं किया।")
        pause()
        return

    if choice != "1":
        print("गलत विकल्प।")
        pause()
        return

    if cv2 is None:
        print("OpenCV उपलब्ध नहीं है। Pydroid में OpenCV install होने पर camera scan संभव होगा।")
        print("फिलहाल manual URL scanner विकल्प इस्तेमाल करें।")
        pause()
        return

    print("📷 कैमरा शुरू करने की कोशिश...")
    print("ध्यान दें: Pydroid में camera permission और OpenCV support जरूरी है।")
    cap = cv2.VideoCapture(0)
    if not cap.isOpened():
        print("कैमरा नहीं खुला। Permission/Android support जाँचें।")
        cap.release()
        pause()
        return

    detector = cv2.QRCodeDetector()
    found = None
    start_time = time.time()

    try:
        while time.time() - start_time < 20:
            ok, frame = cap.read()
            if not ok:
                break
            value, points, _ = detector.detectAndDecode(frame)
            if value:
                found = value
                break
            # A window may work on desktop, but is not guaranteed on Pydroid.
            try:
                cv2.imshow("Aryabhutt QR Scanner - press Q", frame)
                if cv2.waitKey(1) & 0xFF == ord("q"):
                    break
            except Exception:
                # Camera preview is optional on Pydroid.
                print("", end="")
    finally:
        cap.release()
        try:
            cv2.destroyAllWindows()
        except Exception:
            print("", end="")

    if found:
        print("✓ QR में मिला:", found)
    else:
        print("20 seconds में QR नहीं मिला। Manual scanner विकल्प इस्तेमाल करें।")
    pause()


