def analytics_dashboard():
    while True:
        data = load_analytics()
        schools = data.get("schools", {})
        total_schools = len(schools)
        total_students = sum(int(v) for v in schools.values())
        sessions = int(data.get("sessions", 0))
        games_played = int(data.get("games_played", 0))
        riddles_solved = int(data.get("riddles_solved", 0))
        chat_questions = int(data.get("chat_questions", 0))

        print("\n" + "=" * 64)
        print("📊 DATA & ANALYTICS — वास्तविक दर्ज उपयोग")
        print("=" * 64)
        print("अभी नए project में कोई school/student manually दर्ज नहीं है, इसलिए")
        print("नीचे के आँकड़े 0 से शुरू होते हैं। कोई fake संख्या नहीं दिखाई जाती।")

        print("\n--- Multi-school Horizontal Bar Chart ---")
        if not schools:
            print("अभी कोई school दर्ज नहीं है।")
            print("एक school जोड़ने पर वही permanent data यहाँ दिखाई देगा।")
        else:
            for school, students in schools.items():
                count = int(students)
                bar = "█" * (count // 5)
                print(f"{school:<22} | {bar} {count} students")

        print("\n--- Dynamic Metrics Summary ---")
        print(f"Registered Schools : {total_schools}")
        print(f"Registered Students: {total_students}")
        print(f"App Sessions       : {sessions}")
        print(f"Games Played       : {games_played}")
        print(f"Riddles Solved     : {riddles_solved}")
        print(f"Chat Questions     : {chat_questions}")

        print("\n1. स्कूल/छात्र संख्या दर्ज करें")
        print("2. किसी school की संख्या बदलें")
        print("3. पूरा local analytics reset करें")
        print("4. 🔬 IRIS Special Analytical View")
        print("5. 📈 Performance Graph")
        print("6. ☁️ Cloud/Data Sync export")
        print("7. 🔐 Teacher/Admin Dashboard")
        print("8. 🧑‍🎓 Student Live Database")
        print("0. वापस")
        choice = input("चुनें: ").strip()

        if choice == "0":
            return

        if choice == "1":
            school = input("School का नाम: ").strip()
            if not school:
                print("School name जरूरी है।")
                continue
            raw = input("इस school के active students: ").strip()
            try:
                students = max(0, int(raw))
            except ValueError:
                print("संख्या दर्ज करें।")
                continue
            schools[school] = students
            data["schools"] = schools
            data["students"] = sum(int(v) for v in schools.values())
            save_analytics(data)
            print("✓ यह school permanent local analytics में save हो गया।")
            print("अगली बार भी यही data रहेगा।")
            continue

        if choice == "2":
            if not schools:
                print("पहले school जोड़ें।")
                continue
            for i, school in enumerate(schools, 1):
                print(f"{i}. {school} — {schools[school]} students")
            try:
                index = int(input("किसे बदलना है? ")) - 1
                school = list(schools.keys())[index]
            except Exception:
                print("गलत चयन।")
                continue
            raw = input(f"{school} के नए students: ").strip()
            try:
                schools[school] = max(0, int(raw))
            except ValueError:
                print("संख्या दर्ज करें।")
                continue
            data["schools"] = schools
            data["students"] = sum(int(v) for v in schools.values())
            save_analytics(data)
            print("✓ संख्या update हो गई।")
            continue

        if choice == "3":
            confirm = norm(input("सच में सभी local analytics 0 करना है? (हाँ/नहीं): "))
            if confirm in {"हाँ", "ha", "yes", "y"}:
                save_analytics(default_analytics())
                print("✓ Analytics reset: अब सभी आँकड़े 0 हैं।")
            continue

        print("गलत विकल्प।")


