USED_RIDDLES_FILE = os.path.join(os.getcwd(), "aryabhutt_used_riddles.json")

EXIT_WORDS = {"e", "exit", "bye"}
BACK_WORDS = EXIT_WORDS | {"back", "वापस", "निकास", "बाय"}

def is_exit(value):
    return norm(value) in EXIT_WORDS

def is_back(value):
    return norm(value) in BACK_WORDS

def wait_enter():
    input("\n↩️ Enter दबाएँ...")

