def default_analytics_v5():
    return {
        "schools": {}, "student_records": [], "sessions": 0, "games_played": 0,
        "riddles_solved": 0, "chat_questions": 0, "study_views": 0,
        "formula_views": 0, "story_points_read": 0, "reports_generated": 0,
        "math_solved": 0, "astronomy_views": 0, "feedback": [],
        "activity_log": [], "created_at": datetime.now().isoformat(timespec="seconds"),
        "last_updated": None,
    }

def load_analytics():
    data = load_json(DATA_FILE, {})
    base = default_analytics_v5()
    if not isinstance(data, dict): data = {}
    for k,v in base.items(): data.setdefault(k,v)
    # Migrate old student count safely.
    if data.get("student_records") and not isinstance(data["student_records"], list): data["student_records"]=[]
    return data

def save_analytics(data):
    data["last_updated"] = datetime.now().isoformat(timespec="seconds")
    save_json(DATA_FILE, data)

def log_activity(kind, amount=1):
    data=load_analytics(); now=datetime.now()
    data["activity_log"].append({"kind":kind,"amount":int(amount),"time":now.isoformat(timespec="seconds")})
    data["activity_log"] = data["activity_log"][-5000:]
    save_analytics(data)

def inc_metric(key, amount=1, kind=None):
    data=load_analytics(); data[key]=int(data.get(key,0))+int(amount); save_analytics(data)
    if kind: log_activity(kind, amount)

def record_session(): inc_metric("sessions",1,"session")
def record_chat_question(): inc_metric("chat_questions",1,"chat")
def record_game(): inc_metric("games_played",1,"game")
def record_riddle(): inc_metric("riddles_solved",1,"riddle")

