def animal_guessing():
    animals=[("शेर","जंगल का प्रसिद्ध शिकारी"),("हाथी","बहुत बड़ा स्थल-जीव, सूँड होती है"),("बाघ","शरीर पर धारियाँ"),("खरगोश","तेज़ दौड़ने वाला छोटा स्तनपायी"),("ऊँट","रेगिस्तान के लिए अनुकूलित"),("मोर","भारत का राष्ट्रीय पक्षी"),("डॉल्फिन","जल में रहने वाला स्तनपायी"),("पेंगुइन","उड़ नहीं सकता, अच्छा तैरता है")]; n=ask_rounds();
    if n is None:return
    score=0
    for r in range(1,n+1):
        name,h=random.choice(animals); x=input(f"\n🦁 Round {r}/{n} Hint: {h}\nआपका उत्तर | E=बाहर: ").strip()
        if is_exit(x): finish_game("Animal Guessing",score,r-1); return
        if norm(x)==norm(name): score+=1; print("🎉 सही!")
        else: print("❌ सही उत्तर:",name)
    finish_game("Animal Guessing",score,n)

def click_speed():
    n=ask_rounds();
    if n is None:return
    score=0
    for r in range(1,n+1):
        a=input(f"\n🚀 Round {r}/{n} Ready? Enter | E=बाहर: ").strip()
        if is_exit(a): finish_game("Click Speed Test",score,r-1); return
        if a: print("⚠️ Enter या E।"); continue
        time.sleep(random.uniform(.4,1.1)); start=time.perf_counter(); x=input("🚀 GO! Enter NOW! | E=बाहर: ").strip()
        if is_exit(x): finish_game("Click Speed Test",score,r-1); return
        t=time.perf_counter()-start; print(f"⏱️ {t:.3f}s"); score+=t<1.0
