# -------------------- TIMETABLE 4 WEEKS --------------------
DAYS=["Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"]
TIMES=["8:00–8:40","8:40–9:20","9:20–10:00","10:00–10:40","10:40–11:20","11:20–12:00"]
def default_timetable_v5(): return {f"Week {w}":{d:[{"time":TIMES[p],"subject":""} for p in range(6)] for d in DAYS} for w in range(1,5)}
def load_timetable():
    d=load_json(TIMETABLE_FILE,{})
    if not isinstance(d,dict): d={}
    base=default_timetable_v5()
    # migrate old flat timetable into week 1 if present
    for w in base:
        d.setdefault(w,base[w])
        for day in DAYS:
            d[w].setdefault(day,base[w][day])
            for p in range(6):
                if not isinstance(d[w][day][p],dict): d[w][day][p]={"time":TIMES[p],"subject":str(d[w][day][p] or "")}
                d[w][day][p].setdefault("time",TIMES[p]); d[w][day][p].setdefault("subject","")
    return d
def show_timetable():
    d=load_timetable(); title("4-WEEK STUDY TIMETABLE", "📅")
    for w in d:
        print(f"\n📘 {w}")
        for day in DAYS:
            vals=d[w][day]; print(f"  📍 {day}")
            for i,x in enumerate(vals,1): print(f"    Period {i} | {x['time']} → {x['subject'] or '—'}")
    wait_enter()
def edit_timetable():
    d=load_timetable()
    while True:
        title("EDIT TIMETABLE — WEEK / DAY / PERIOD", "✏️")
        print("1–4 = Week चुनें | E = Save & Exit")
        w=input("Week: ").strip()
        if is_exit(w): save_json(TIMETABLE_FILE,d); print("💾 Partial timetable saved!"); return
        if w not in {"1","2","3","4"}: print("⚠️ 1 से 4 चुनो।"); continue
        week=f"Week {w}"
        for i,day in enumerate(DAYS,1): print(f"{i}. {day}")
        dayc=input("Day (E=save & exit): ").strip()
        if is_exit(dayc): save_json(TIMETABLE_FILE,d); return
        if not dayc.isdigit() or not 1<=int(dayc)<=6: print("⚠️ सही day चुनो।"); continue
        day=DAYS[int(dayc)-1]
        while True:
            for i,x in enumerate(d[week][day],1): print(f"{i}. Period {i} | {x['time']} | {x['subject'] or '—'}")
            pc=input("Period (E=save & exit): ").strip()
            if is_exit(pc): save_json(TIMETABLE_FILE,d); return
            if not pc.isdigit() or not 1<=int(pc)<=6: print("⚠️ सही period चुनो।"); continue
            p=int(pc)-1; sub=input(f"Subject for {week} {day} Period {p+1} ({d[week][day][p]['time']}) | E=save: ").strip()
            if is_exit(sub): save_json(TIMETABLE_FILE,d); return
            d[week][day][p]["subject"]=sub; save_json(TIMETABLE_FILE,d); print("✅ Saved. Continue or E.")

