# -------------------- QR / URL --------------------
def qr_scanner():
    while True:
        title("QR / URL SCANNER", "📷")
        print("1. 📷 Camera QR Scan\n2. 🔗 Manual URL/Text\nE. Back")
        c=input("Choose: ").strip()
        if is_exit(c): return
        if c=="2":
            v=input("URL/Text | E=back: ").strip()
            if is_exit(v): return
            if v.startswith(("http://","https://")): print("🔗 URL detected:",v)
            elif v: print("📝 Text detected:",v)
            else: print("⚠️ Empty input")
            wait_enter(); continue
        if c!="1": print("⚠️ गलत विकल्प।"); continue
        if cv2 is None:
            print("🟡 Camera scanner इस device पर उपलब्ध नहीं है।"); print("➡️ Manual URL/Text fallback इस्तेमाल करो।"); wait_enter(); continue
        print("📷 Camera starting... E is available only before camera starts.")
        cap=cv2.VideoCapture(0)
        if not cap.isOpened(): print("🟡 Camera नहीं खुला — permission/support issue हो सकता है।"); cap.release(); wait_enter(); continue
        detector=cv2.QRCodeDetector(); found=None; start=time.time()
        try:
            while time.time()-start<20:
                ok,frame=cap.read()
                if not ok: break
                val,points,_=detector.detectAndDecode(frame)
                if val: found=val; break
                try:
                    cv2.imshow("Aryabhutt QR - Q to stop",frame)
                    if cv2.waitKey(1)&0xFF==ord('q'): break
                except Exception: pass
        finally:
            cap.release()
            try: cv2.destroyAllWindows()
            except Exception: pass
        print("✅ QR Data:" if found else "⚠️ QR नहीं मिला। Manual fallback चुनो।",found or "")
        wait_enter()

