        d=load_analytics(); students=d.setdefault("student_records",[])
        print("1. ➕ Add student\n2. 📋 List students\n3. ✏️ Edit student\n4. 🗑️ Delete student\n5. 📊 Student activity\nE. Back")
        c=input("Choose: ").strip()
