def filtered_counts(days):
    d=load_analytics(); now=datetime.now(); cutoff=now-timedelta(days=days) if days else None; out={}
    for e in d.get("activity_log",[]):
        try:t=datetime.fromisoformat(e["time"])
        except:continue
        if cutoff and t<cutoff: continue
        out[e["kind"]]=out.get(e["kind"],0)+int(e.get("amount",1))
    return out

def real_dashboard():
    while True:
        title("REAL ACTIVITY DASHBOARD", "📊")
        print("These are real local activity records — no fake score/ranking.\n")
        print("1. Today\n2. Last 7 Days\n3. Last 30 Days\n4. All Time\nE. Back")
        c=input("Time filter: ").strip()
