    print("📌 " + title_text)
    print("🧮 Formula / सूत्र:")
    print("   " + formula)
    print("🇮🇳 हिन्दी में अर्थ:")
    print("   " + meaning)
    print("💡 Example / उदाहरण:")
    print("   " + example)
    print("─" * 62)


