def formula_bank():
    topics = list(FORMULA_BANK_HI)
    while True:
        title("IMPORTANT MATHS FORMULA BANK • 100+ SPACED CARDS", "📚")
        print("💡 हर formula के साथ हिन्दी अर्थ और छोटा example भी दिया गया है।\n")
        for i, topic in enumerate(topics, 1):
            print(f"  {i:>2}. 🧮 {topic}  ({len(FORMULA_BANK_HI[topic])} सूत्र)")
        print("\n  E. ↩️ वापस")
        x = input("\n👉 Topic चुनें: ").strip()
        if is_exit(x):
            return
        if not x.isdigit() or not 1 <= int(x) <= len(topics):
            print("⚠️ कृपया ऊपर दिए गए topic number में से चुनें।")
            continue
        topic = topics[int(x)-1]
        title(topic, "🧮")
        for card in FORMULA_BANK_HI[topic]:
            _formula_card(*card)
        inc_metric("formula_views", 1, "formula")
        wait_enter()


