def definitions_bank():
    while True:
        title("MATHS DEFINITIONS • हिन्दी + English", "📖")
        print("1. 🔢 Class 3–5 Foundations")
        print("2. 🧮 Class 6–9 Main Definitions")
        print("3. 📚 ALL Definitions")
        print("E. ↩️ Back")
        x=input("\n👉 Choose: ").strip()
        if is_exit(x): return
        if x not in {"1","2","3"}:
            print("⚠️ 1, 2 या 3 चुनें।")
            continue
        total=len(DEFINITIONS_HI)
        if x=="1": subset=DEFINITIONS_HI[:24]
        elif x=="2": subset=DEFINITIONS_HI[24:]
        else: subset=DEFINITIONS_HI
        title(f"DEFINITIONS • {len(subset)} CARDS", "📖")
        for i,(en,hi,meaning,example) in enumerate(subset,1):
            print("\n" + "─"*62)
            print(f"📘 {i:02d}. {en} — {hi}")
            print("📝 अर्थ / Meaning:")
            print("   " + meaning)
            print("💡 Example / उदाहरण:")
            print("   " + example)
        print("─"*62)
        inc_metric("study_views",1,"definitions")
        wait_enter()


