# Real activity filters accept both menu numbers and readable words.
def filtered_counts(days):
    d=load_analytics(); now=datetime.now(); cutoff=now-timedelta(days=days) if days else None; out={}
    for e in d.get("activity_log",[]):
        try: t=datetime.fromisoformat(e["time"])
        except Exception: continue
        if cutoff and t < cutoff: continue
        out[e.get("kind","unknown")]=out.get(e.get("kind","unknown"),0)+int(e.get("amount",1))
    return out


