def _export_dir():
    candidates=[]
    if os.path.isdir("/storage/emulated/0/Download"):
        candidates.append("/storage/emulated/0/Download/PROJECT_ARYABHUTT")
    if os.path.isdir("/storage/emulated/0/Documents"):
        candidates.append("/storage/emulated/0/Documents/PROJECT_ARYABHUTT")
    candidates.append(os.path.join(os.getcwd(),"PROJECT_ARYABHUTT_Backups"))
    for path in candidates:
        try:
            os.makedirs(path,exist_ok=True)
            return path
        except Exception:
            continue
    return os.getcwd()


def cloud_data_sync():
    while True:
        title("DATA SYNC • LOCAL BACKUP", "☁️")
