# ===================== V5.2 JUDGE-FRIENDLY POLISH PATCH =====================
# This layer fixes the screens tested on-device without replacing the existing
# V5/V5+ learning, games, voice, Gemini and visualizer modules.
import shutil as _shutil

VERSION = "V5.2"

# ---------- Persistent app settings ----------
_BASE_LOAD_ANALYTICS = load_analytics
_BASE_SAVE_ANALYTICS = save_analytics

def load_analytics():
    data = _BASE_LOAD_ANALYTICS()
    settings = data.setdefault("settings", {})
    global LANGUAGE, FOCUS_MODE
    LANGUAGE = settings.get("language", LANGUAGE)
    FOCUS_MODE = bool(settings.get("focus_mode", FOCUS_MODE))
    return data

def save_analytics(data):
    settings = data.setdefault("settings", {})
    settings["language"] = LANGUAGE
    settings["focus_mode"] = bool(FOCUS_MODE)
    return _BASE_SAVE_ANALYTICS(data)


def _ui(hi, en):
    return en if LANGUAGE == "en" else hi


def _report_root():
    candidates = [
        "/storage/emulated/0/Download/PROJECT_ARYABHUTT/Reports",
        "/storage/emulated/0/Documents/PROJECT_ARYABHUTT/Reports",
        os.path.join(os.getcwd(), "PROJECT_ARYABHUTT", "Reports"),
    ]
    for path in candidates:
        try:
            os.makedirs(path, exist_ok=True)
            return path
        except Exception:
            continue
    return os.getcwd()


def _backup_root():
    return _export_dir()


def _report_path():
    return os.path.join(_report_root(), "report_card_latest.txt")


def _feedback_path():
    root = _report_root()
    return os.path.join(root, "feedback.txt")


def _friendly_path(path):
    return path.replace("/storage/emulated/0/", "Internal Storage/")


# ---------- Language: persistent and clearly explained ----------
