            print("\n✅ हिन्दी UI mode active.")
            print("💡 Main Menu, Settings, Reports, Data/Sync और Update screens अब हिन्दी-first दिखेंगे।")
            print("ℹ️ कुछ educational names/technical terms bilingual रहेंगे ताकि meaning clear रहे।")
