# ---------- Feedback: rating + custom written feedback ----------
def feedback_menu():
    title(_ui("FEEDBACK / प्रतिक्रिया", "FEEDBACK / प्रतिक्रिया"), "💬")
    print("1. 🌟 Excellent")
    print("2. 👍 Good")
    print("3. 🙂 Okay")
    print("4. 🛠️ Needs Improvement")
    print("5. ✍️ " + _ui("Write my own feedback", "Write my own feedback"))
    print("E. ↩️ " + _ui("Back", "Back"))
    c = input("\n👉 " + _ui("Your choice", "Your choice") + ": ").strip()
    if is_exit(c):
        return
    labels = {"1":"Excellent", "2":"Good", "3":"Okay", "4":"Needs Improvement"}
    rating = labels.get(c, "Custom")
    comment = ""
    if c == "5":
        comment = input("✍️ " + _ui("अपनी feedback लिखो", "Write your feedback") + " (E=cancel): ").strip()
        if is_exit(comment):
            return
        if not comment:
            print("⚠️ Feedback खाली नहीं होना चाहिए।")
            wait_enter(); return
    elif c not in labels:
        print("⚠️ 1–5 या E चुनें।")
        wait_enter(); return
    else:
        comment = input("📝 " + _ui("कोई छोटा comment जोड़ना है? (Enter = skip)", "Add a short comment? (Enter = skip)") + ": ").strip()
        if is_exit(comment):
            comment = ""
    d = load_analytics()
    d.setdefault("feedback", []).append({
        "rating": rating,
        "comment": comment,
        "time": datetime.now().isoformat(timespec="seconds"),
    })
    save_analytics(d)
    try:
        with open(_feedback_path(), "a", encoding="utf-8") as f:
            f.write(f"{datetime.now().isoformat(timespec='seconds')} | {rating} | {comment}\n")
    except Exception:
        pass
    print("\n✅ " + _ui("Feedback saved locally. धन्यवाद!", "Feedback saved locally. Thank you!"))
    wait_enter()


