# ===================== FINAL GEMINI ONLINE FIX =====================
# Fixes repeated API-key prompts on Pydroid/Android and prevents a false
# "ONLINE" status when the key/client has not actually reached Gemini.
# The key is stored outside the Python source in a stable app folder.

import os as _os
import shutil as _shutil


def _choose_project_storage():
    candidates = []
    android_root = "/storage/emulated/0"
    if _os.path.isdir(android_root):
        candidates.append(_os.path.join(android_root, "PROJECT_ARYABHUTT"))
    candidates.append(_os.path.join(_os.path.expanduser("~"), "PROJECT_ARYABHUTT"))
    candidates.append(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "PROJECT_ARYABHUTT_DATA"))
    for folder in candidates:
        try:
            _os.makedirs(folder, exist_ok=True)
            test_file = _os.path.join(folder, ".write_test")
            with open(test_file, "w", encoding="utf-8") as f:
                f.write("ok")
            try:
                _os.remove(test_file)
            except Exception:
                pass
            return folder
        except Exception:
            continue
    return _os.path.dirname(_os.path.abspath(__file__))


PROJECT_STORAGE_DIR = _choose_project_storage()
GEMINI_KEY_FILE = _os.path.join(PROJECT_STORAGE_DIR, "gemini_api_key.txt")
GEMINI_MODEL = "gemini-3.8-flash"


def get_api_key():
    """Stable key lookup: environment first, then persistent Android/app file."""
    key = _os.environ.get("GEMINI_API_KEY") or _os.environ.get("GOOGLE_API_KEY")
    if key and key.strip():
        return key.strip()
    paths = [GEMINI_KEY_FILE]
    # One-time migration from the old current-working-directory location.
    old_path = _os.path.join(_os.getcwd(), "gemini_api_key.txt")
    if old_path not in paths:
        paths.append(old_path)
    for path in paths:
        try:
            if _os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    value = f.read().strip()
                if value:
                    if path != GEMINI_KEY_FILE:
                        try:
                            save_api_key(value)
                        except Exception:
                            pass
                    return value
        except Exception:
            continue
    return None


def save_api_key(key):
    key = str(key).strip()
    if not key:
        return False
    try:
        _os.makedirs(PROJECT_STORAGE_DIR, exist_ok=True)
        with open(GEMINI_KEY_FILE, "w", encoding="utf-8") as f:
            f.write(key)
        return True
    except Exception as exc:
        print("⚠️ API key save error:", str(exc)[:140])
        return False


def make_gemini_client():
    if genai is None:
        return None
    key = get_api_key()
    if not key:
        return None
    try:
        return genai.Client(api_key=key)
    except Exception as exc:
        print("⚠️ Gemini client error:", str(exc)[:180])
        return None


def _gemini_connection_test(client):
    """Return (ok, short_reason). Makes one tiny real API call so the UI never lies."""
    if client is None:
        if genai is None:
            return False, "google-genai package installed नहीं है"
        return False, "API key नहीं मिली"
    try:
        response = client.models.generate_content(
            model=GEMINI_MODEL,
            contents="Reply with only: OK",
        )
        text = getattr(response, "text", None)
        if text and str(text).strip():
            return True, "Connection successful"
        return False, "Gemini ने empty response दिया"
    except Exception as exc:
        msg = str(exc).replace("\n", " ").strip()
        # Keep diagnostics useful without printing the API key.
        low = msg.lower()
        if "api key" in low or "permission" in low or "unauth" in low:
            return False, "API key invalid/unauthorized है"
        if "quota" in low or "resource exhausted" in low:
            return False, "API quota/rate limit reached है"
        if "not found" in low or "404" in low:
            return False, f"Model {GEMINI_MODEL} उपलब्ध नहीं है"
        if "timeout" in low or "timed out" in low:
            return False, "Network timeout — internet check करो"
        return False, msg[:180] or "Unknown Gemini error"


def setup_gemini_key():
    from getpass import getpass
    title("GEMINI ONLINE MODE SETUP", "🌐")
    print("🔐 Gemini API key एक बार डालो — यह app के stable folder में save होगी।")
    print("📁 Save location:")
    print("   " + GEMINI_KEY_FILE)
    print("🛡️ Key Python code में नहीं लिखी जाएगी।")
    print("↩️ E / EXIT / BYE = वापस")
    try:
        key = getpass("🔑 Gemini API key: ").strip()
    except Exception:
        key = input("🔑 Gemini API key: ").strip()
    if is_exit(key):
        return False
    if len(key) < 20:
        print("⚠️ API key बहुत छोटी लग रही है। सही Gemini key डालें।")
        return False
    if not save_api_key(key):
        print("❌ Key save नहीं हो सकी। Storage permission/check करें।")
        return False
    print("✅ API key permanently saved.")
    client = make_gemini_client()
    print("🌐 Connection test चल रहा है...")
    ok, reason = _gemini_connection_test(client)
    if ok:
        print("🟢 ONLINE MODE READY — Gemini successfully connected.")
        return True
    print("🔴 ONLINE MODE अभी connect नहीं हुआ।")
    print("ℹ️ Reason:", reason)
    print("📚 Offline mode फिर भी पूरी तरह चलता रहेगा।")
    return False


