# ===================== V5.6 FINAL GEMINI + VOICE FIX =====================
# Keep the complete V5.6 app. Only the chatbot's online/fallback behavior is
# corrected here. Direct Gemini is used from Pydroid 3; no backend URL.
VERSION = "V5.6"
GEMINI_MODEL = "gemini-2.5-flash"
GEMINI_MAX_ATTEMPTS = 3
GEMINI_RETRY_DELAY_SECONDS = 2


def _offline_lookup(question):
    """Safe offline lookup: direct knowledge first, then conservative fuzzy match."""
    q = norm(question)
    try:
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                if norm(key) in q:
                    return True, str(answer)

        # Avoid surprising matches for short/unknown questions.
        best_answer = None
        best_score = 0.0
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                key_n = norm(key)
                score = difflib.SequenceMatcher(None, q, key_n).ratio()
                if score > best_score:
                    best_score = score
                    best_answer = answer
        threshold = 0.72 if len(q.split()) <= 5 else 0.68
        if best_answer is not None and best_score >= threshold:
            return True, str(best_answer)
    except Exception:
        pass
    return False, ""


def _offline_lookup_found(question):
    return _offline_lookup(question)[0]


def _offline_message(question, mode):
    """Truthful fallback: never pretends an unknown question was answered."""
    found, answer = _offline_lookup(question)
    if found:
        return (
            "📚 [OFFLINE MODE — Local Knowledge]\n"
            "⚠️ Gemini अभी उपलब्ध नहीं है। इसलिए नीचे मेरी Offline Knowledge Book से उत्तर है।\n"
            "🪷 " + answer
        ), answer
    message = (
        "📚 [OFFLINE MODE — Local Knowledge]\n"
        "⚠️ Gemini अभी उपलब्ध नहीं है।\n"
        "❌ मेरी Offline Knowledge Book में इस प्रश्न का उत्तर नहीं है।\n"
        "💡 Gemini उपलब्ध होने पर फिर यही प्रश्न पूछें, या किसी विश्वसनीय स्रोत से जानकारी लें।"
    )
    return message, message

def gemini_answer(question, client):
    """Try Gemini exactly 3 times, waiting 2 seconds between attempts.

    A temporary 503/high-demand error therefore gets two retries before the
    app falls back to the local knowledge book.
    """
    if client is None:
        return None, "no_client"

    prompt = (
        "You are Acharya Aryabhatta, a friendly Class 8 educational assistant. "
        "Answer in simple Hindi/Hinglish unless the student asks in English. "
        "Be accurate, child-friendly and concise. Never invent historical facts. "
        "Do not mention internal API, model, server or system details in the answer.\n\n"
        "Student question: " + str(question)
    )

    last_error = ""
    for attempt in range(1, GEMINI_MAX_ATTEMPTS + 1):
        try:
            # Keep the request simple and compatible with the official SDK.
            response = client.models.generate_content(
                model=GEMINI_MODEL,
                contents=prompt,
            )
            answer = getattr(response, "text", None)
            if answer and str(answer).strip():
                return str(answer).strip(), "online"
            last_error = "empty response"
        except Exception as exc:
            last_error = str(exc)[:180]

        if attempt < GEMINI_MAX_ATTEMPTS:
            print(f"⏳ Gemini कोशिश {attempt}/3 असफल — 2 सेकंड बाद फिर कोशिश...")
            time.sleep(GEMINI_RETRY_DELAY_SECONDS)

    return None, "online_error:" + last_error


def _offline_message(question, mode):
    """Return a truthful offline status + answer without pretending Gemini replied."""
    found = _offline_lookup_found(question)
    answer = offline_answer(question)
    if found:
        return (
            "📚 [OFFLINE MODE — Local Knowledge]\n"
            "⚠️ Gemini अभी उपलब्ध नहीं है। इसलिए नीचे मेरी Offline Knowledge Book से उत्तर है।\n"
            "🪷 " + str(answer)
        )
