# ===================== V5.6 FINAL STABILITY PATCH =====================
# Final override: current stable Gemini model + exact retry/fallback behavior.
# This patch fixes the previous "too many values to unpack" crash.
VERSION = "V5.6"
GEMINI_MODEL = "gemini-3.8-flash"
GEMINI_MAX_ATTEMPTS = 3
GEMINI_RETRY_DELAY_SECONDS = 2


def _v56_gemini_error_text(exc):
    msg = str(exc).replace("\n", " ").strip()
    low = msg.lower()
    if "api key" in low or "permission" in low or "unauth" in low:
        return "API key invalid/unauthorized है।"
    if "quota" in low or "resource exhausted" in low or "429" in low:
        return "Gemini API quota/rate limit अभी उपलब्ध नहीं है।"
    if "503" in low or "unavailable" in low or "high demand" in low:
        return "Gemini server अभी temporarily busy/unavailable है।"
    if "404" in low or "not found" in low:
        return f"Gemini model {GEMINI_MODEL} उपलब्ध नहीं है।"
    if "timeout" in low or "timed out" in low:
        return "Network timeout हुआ है। Internet connection check करें।"
    return msg[:180] or "Gemini से उत्तर नहीं मिला।"


def _v56_offline_lookup(question):
    q = norm(question)
    try:
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                if norm(key) in q:
                    return True, str(answer)
        # Conservative fuzzy matching prevents unrelated answers.
        best_answer = None
        best_score = 0.0
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                key_n = norm(key)
                if not key_n:
                    continue
                score = difflib.SequenceMatcher(None, q, key_n).ratio()
                if score > best_score:
                    best_score = score
                    best_answer = answer
        threshold = 0.76 if len(q.split()) <= 5 else 0.70
        if best_answer is not None and best_score >= threshold:
            return True, str(best_answer)
    except Exception:
        pass
    return False, ""


def _v56_offline_display(question, reason):
    found, answer = _v56_offline_lookup(question)
    if found:
        text = (
            "📚 [OFFLINE MODE — Local Knowledge]\n"
            "⚠️ Gemini अभी उपलब्ध नहीं है। इसलिए नीचे मेरी Offline Knowledge Book से उत्तर है।\n"
            "🪷 आचार्य आर्यभट्ट: " + answer
        )
        return text, answer
    text = (
        "📚 [OFFLINE MODE — Local Knowledge]\n"
        "⚠️ Gemini अभी उपलब्ध नहीं है।\n"
        "❌ मेरी Offline Knowledge Book में इस प्रश्न का उत्तर नहीं है।\n"
        "💡 Gemini उपलब्ध होने पर फिर यही प्रश्न पूछें, या किसी विश्वसनीय स्रोत से जानकारी लें।"
    )
    return text, text


def gemini_answer(question, client):
    """Exactly 3 Gemini attempts, 2-second gaps, with Hindi-only output."""
    if client is None:
        return None, "no_client"

    # IMPORTANT: The project is Hindi-first. Even if the student types the
    # question in English, Gemini must answer in Hindi/Devanagari.
    prompt = (
        "You are Acharya Aryabhatta, a friendly Class 8 educational assistant.\n"
        "IMPORTANT LANGUAGE RULE: Always answer the student in simple, clear Hindi "
        "using Devanagari script. Do NOT answer in English, even when the student "
        "asks the question in English. Keep proper names, scientific terms, or "
        "short technical terms in English only when necessary, with their Hindi "
        "explanation. Do not use English paragraphs.\n"
        "Be accurate, child-friendly, concise, and educational. Never invent facts.\n\n"
        "Student question: " + str(question)
    )
    last_reason = "Gemini से उत्तर नहीं मिला।"

    # Use the Chat API to avoid the AFC warning produced by direct
    # Models.generate_content calls in some google-genai/Pydroid versions.
    chat = None
    try:
        chat = client.chats.create(model=GEMINI_MODEL)
    except Exception:
        chat = None

    for attempt in range(1, 4):
        try:
            if chat is not None:
                response = chat.send_message(prompt)
            else:
                # Compatibility fallback for older google-genai versions.
                response = client.models.generate_content(
                    model=GEMINI_MODEL,
                    contents=prompt,
                )
            answer = getattr(response, "text", None)
            if answer and str(answer).strip():
                return str(answer).strip(), "online"
            last_reason = "Gemini ने empty response दिया।"
        except Exception as exc:
            last_reason = _v56_gemini_error_text(exc)
            if attempt < 3:
                print(f"⏳ Gemini कोशिश {attempt}/3 असफल — 2 सेकंड बाद फिर कोशिश...")
                time.sleep(2)
    return None, "online_error:" + last_reason


def _v56_print_status(client):
    if genai is None:
        print("🔴 Online Gemini उपलब्ध नहीं: google-genai package नहीं मिला।")
        return
    if client is None:
        print("🟡 Online Gemini अभी configured नहीं है — Offline backup ready है।")
        return
    # Do not perform a hidden extra model call here. The real question will
    # get its own 3 attempts, so a temporary 503 does not create confusion.
    print(f"🌐 Gemini model: {GEMINI_MODEL} | भाषा: हिंदी (देवनागरी) | 3 attempts × 2 sec retry")


