def _v56_acharya_persona(answer):
    """Make both online and offline answers sound like a warm Acharya, not a translation bot."""
    text = str(answer).strip()
    if not text:
        return text
    # Avoid duplicate sign-offs if Gemini already supplied one.
    lower = text.lower()
    if "आयुष्मान भव" not in text and "आयुष्मान भव" not in lower:
        text += "\n\n🌼 वत्स, ज्ञान को जिज्ञासा और अभ्यास से और उज्ज्वल बनाओ। आयुष्मान भव!"
