def _v56_offline_lookup(question):
    extra=_v56_extra_knowledge(question)
    if extra: return True, extra
    q=norm(question)
    try:
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                kn=norm(key)
                if kn and (kn in q or q in kn):
                    return True, str(answer)
        # Token-aware fuzzy matching, but don't let a generic one-word key win for a specific question.
        best_answer=None; best_score=0.0
        qwords=set(q.split())
        for keys, answer in OFFLINE_KNOWLEDGE:
            for key in keys:
                kn=norm(key)
                if not kn or len(kn)<4: continue
                score=difflib.SequenceMatcher(None,q,kn).ratio()
                overlap=len(qwords & set(kn.split()))/max(1,len(qwords))
                score=max(score, 0.65*score+0.35*overlap)
                if score>best_score:
                    best_score=score; best_answer=answer
        if best_answer is not None and best_score>=0.62:
            return True,str(best_answer)
    except Exception:
        pass
    return False,""


def _v56_acharya_persona(answer):
    text=str(answer).strip()
    if not text: return text
    if "आयुष्मान भव" not in text and "ज्ञानवान भव" not in text:
        text += "\n\n🌼 वत्स, ज्ञान की ज्योति जलाए रखो। आयुष्मान भव!"
    return text


def _v56_offline_display(question, reason):
    found,answer=_v56_offline_lookup(question)
    if found:
        answer=_v56_acharya_persona(answer)
        return ("📚 [OFFLINE MODE — Local Knowledge]\n"
                "⚠️ Gemini अभी उपलब्ध नहीं है, इसलिए नीचे मेरी Offline Knowledge Book से उत्तर है।\n"
                "🪷 आचार्य आर्यभट्ट: "+answer, answer)
    text=("📚 [OFFLINE MODE — Local Knowledge]\n"
          "⚠️ Gemini इस समय उपलब्ध नहीं है।\n"
          "❌ मेरी Offline Knowledge Book में इस प्रश्न का उत्तर अभी नहीं मिला।\n"
          "💡 वत्स, Internet/Gemini उपलब्ध होने पर यही प्रश्न फिर पूछना।\n"
          "🌼 आयुष्मान भव!")
    return text,text


def _v56_gemini_error_text(exc):
    msg=str(exc).replace("\n"," ").strip(); low=msg.lower()
    if "api key" in low or "permission" in low or "unauthor" in low or "401" in low or "403" in low:
        return "API key invalid/unauthorized है।"
    if "quota" in low or "resource exhausted" in low or "429" in low or "rate limit" in low:
        return "Gemini API quota/rate limit अभी उपलब्ध नहीं है।"
    if "503" in low or "unavailable" in low or "high demand" in low:
        return "Gemini server अभी temporarily busy/unavailable है।"
    if "404" in low or "not found" in low:
        return f"Gemini model {GEMINI_MODEL} उपलब्ध नहीं है।"
    if "timeout" in low or "timed out" in low or "urlopen error" in low or "network" in low:
        return "Network timeout/connection समस्या हुई है। Internet connection check करें।"
    return msg[:180] or "Gemini से उत्तर नहीं मिला।"


def _v56_rest_gemini(question, api_key):
    """Direct official REST fallback. This bypasses SDK version/AFC quirks."""
    prompt=(
      "तुम आचार्य आर्यभट्ट नाम के स्नेही भारतीय शिक्षक हो। विद्यार्थी से सीधे बात करो। "
      "हर उत्तर सरल स्वाभाविक हिंदी/देवनागरी में दो, English में प्रश्न हो तब भी हिंदी में। "
      "'वत्स', 'बच्चा', 'प्रिय विद्यार्थी' जैसे संबोधन स्वाभाविक रूप से उपयोग करो। "
      "सही, शैक्षिक, उम्र-उपयुक्त उत्तर दो; तथ्य मत गढ़ो; जरूरत हो तो उदाहरण दो; अंत में छोटा 'आयुष्मान भव!' आशीर्वचन दो।\n\n"
      "विद्यार्थी का प्रश्न: "+str(question)
    )
    url=f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent"
    body={"contents":[{"parts":[{"text":prompt}]}],"generationConfig":{"temperature":0.4,"maxOutputTokens":320}}
    req=_urlreq.Request(url,data=_json.dumps(body,ensure_ascii=False).encode("utf-8"),headers={"Content-Type":"application/json","x-goog-api-key":api_key},method="POST")
    with _urlreq.urlopen(req,timeout=GEMINI_TIMEOUT_SECONDS) as resp:
        data=_json.loads(resp.read().decode("utf-8"))
    parts=data.get("candidates",[{}])[0].get("content",{}).get("parts",[])
    answer="".join(str(p.get("text","")) for p in parts if isinstance(p,dict)).strip()
    if not answer: raise RuntimeError("Gemini ने empty response दिया।")
    return _v56_acharya_persona(answer)


def gemini_answer(question, client=None):
    key=get_api_key()
    if not key: return None,"no_api_key"
    last="Gemini से उत्तर नहीं मिला।"
    for attempt in range(1,GEMINI_MAX_ATTEMPTS+1):
        try:
            # REST first: simple, current official API path and no AFC/tool warning.
            return _v56_rest_gemini(question,key),"online"
        except Exception as exc:
            last=_v56_gemini_error_text(exc)
            # SDK fallback if REST failed and a client exists.
            if client is not None:
                try:
                    response=client.models.generate_content(
                        model=GEMINI_MODEL,
                        contents=("आचार्य आर्यभट्ट के रूप में सरल हिंदी में उत्तर दो। विद्यार्थी का प्रश्न: "+str(question)),
                    )
                    answer=getattr(response,"text",None)
                    if answer and str(answer).strip(): return _v56_acharya_persona(answer),"online"
                except Exception as sdk_exc:
                    last=_v56_gemini_error_text(sdk_exc)
            if attempt<GEMINI_MAX_ATTEMPTS:
                print(f"⏳ Gemini कोशिश {attempt}/{GEMINI_MAX_ATTEMPTS} असफल — {GEMINI_RETRY_DELAY_SECONDS} सेकंड बाद फिर कोशिश...")
                time.sleep(GEMINI_RETRY_DELAY_SECONDS)
    return None,"online_error:"+last


def setup_gemini_key():
    """One-time setup: if a key already exists, never ask for it again."""
    existing=get_api_key()
    title("GEMINI ONLINE MODE — ONE-TIME SETUP","🌐")
    if existing:
        print("🔐 तुम्हारी Gemini API key पहले से सुरक्षित रूप से saved है।")
        print("✅ इसे फिर से डालने की जरूरत नहीं है।")
        print("💡 अगला वास्तविक प्रश्न सीधे Gemini को भेजा जाएगा।")
        print("🔑 Key बदलनी हो तो 'api-reset' लिखो।")
        return True
    print("🔐 पहली बार अपनी Gemini API key डालो।")
    print("🛡️ Key code में नहीं लिखी जाएगी; local file में सुरक्षित रखी जाएगी।")
    try:
        from getpass import getpass
        key=getpass("🔑 Gemini API key: ").strip()
    except Exception:
        key=input("🔑 Gemini API key: ").strip()
    if is_exit(key): return False
    if len(key)<20:
        print("⚠️ API key बहुत छोटी लग रही है।")
        return False
    if save_api_key(key):
        print("✅ API key एक बार के लिए सुरक्षित रूप से save हो गई।")
        return True
    print("❌ API key save नहीं हो सकी।")
    return False


