def ask_rounds():
    while True:
        try:
            raw = input("🎮 Rounds चुनें (1–30) | E = Game छोड़ें: ").strip()
        except (EOFError, KeyboardInterrupt):
            print("\n↩️ Game से वापस जा रहे हैं...")
            return None

        if is_exit(raw):
            print("↩️ Game छोड़ दिया गया।")
            return None

        try:
            n = int(raw)
        except ValueError:
            print("⚠️ केवल संख्या लिखें: 1 से 30।")
            continue

        if 1 <= n <= 30:
            return n

        print("❌ केवल 1–30 rounds चुन सकते हैं।")
        print("   उदाहरण: 3, 5, 10, 20, 30 — सभी मान्य हैं।")


