# =====================================================================
# V5.6 FINAL ONLINE + PYDROID VOICE STABILITY PATCH
# - Keep Gemini on direct REST: no SDK/AFC generate_content warning.
# - Use currently documented stable models.
# - Give a clear quota/key/network diagnosis instead of a misleading error.
# - Disable the broken Plyer/JNIEnv route in Pydroid terminal mode.
# - Voice is best-effort and NEVER prints a traceback or crashes the app.
# =====================================================================

GEMINI_MODEL = "gemini-3.8-flash"
_V56_ONLINE_MODELS = ["gemini-3.8-flash", "gemini-3.5-flash-lite"]
GEMINI_MAX_ATTEMPTS = 3
GEMINI_RETRY_DELAY_SECONDS = 2
GEMINI_TIMEOUT_SECONDS = 12


def _v56_gemini_error_text(exc):
    msg = str(exc).replace("\n", " ").strip()
    low = msg.lower()
    if "429" in low or "quota" in low or "rate limit" in low or "resource_exhausted" in low:
        return "Gemini API quota/rate limit अभी उपलब्ध नहीं है।"
    if "401" in low or "403" in low or "api key" in low or "permission" in low or "unauthenticated" in low:
        return "Gemini API key/permission की समस्या है।"
    if "404" in low or "not found" in low or "model" in low and "available" in low:
        return "इस API key के लिए चुना हुआ Gemini model उपलब्ध नहीं है।"
    if "timed out" in low or "timeout" in low:
        return "Gemini request timeout हुआ।"
    if "urlopen error" in low or "connection" in low or "network" in low:
        return "Internet connection से Gemini तक पहुँचना नहीं हो पाया।"
    return "Gemini server/API ने अभी उत्तर नहीं दिया।"


def _v56_rest_model(question, api_key, model):
    prompt = (
        "तुम PROJECT ARYABHUTT के आचार्य आर्यभट्ट नामक शैक्षिक सहायक हो। "
        "विद्यार्थी के प्रश्न का सही, सरल और उम्र-उपयुक्त उत्तर दो। "
        "प्रश्न Hindi, Hinglish या English में हो सकता है; उत्तर सरल हिन्दी/देवनागरी में दो। "
        "गणित में steps और final answer साफ दो। तथ्य मत गढ़ो। "
        "उत्तर के अंत में छोटा 'आयुष्मान भव!' लिख सकते हो।\n\n"
        "विद्यार्थी का प्रश्न: " + str(question)
    )
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent"
    body = {
        "contents": [{"parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0.2, "maxOutputTokens": 500},
    }
    req = _urlreq.Request(
        url,
        data=_json.dumps(body, ensure_ascii=False).encode("utf-8"),
        headers={"Content-Type": "application/json", "x-goog-api-key": api_key},
        method="POST",
    )
    try:
        with _urlreq.urlopen(req, timeout=GEMINI_TIMEOUT_SECONDS) as resp:
            data = _json.loads(resp.read().decode("utf-8"))
    except Exception as exc:
        # Preserve HTTP status/body when possible so the caller can identify 429/403/404.
        raise RuntimeError(str(exc)) from exc

    candidates = data.get("candidates") or []
    parts = candidates[0].get("content", {}).get("parts", []) if candidates else []
    answer = "".join(str(x.get("text", "")) for x in parts if isinstance(x, dict)).strip()
    if not answer:
        api_msg = data.get("error", {}).get("message") if isinstance(data.get("error"), dict) else None
        raise RuntimeError(api_msg or "Gemini ने खाली उत्तर दिया।")
    return _v56_acharya_persona(answer)


def gemini_answer(question, client=None):
    key = get_api_key()
    if not key:
        return None, "no_api_key"

    last_reason = "Gemini server/API ने अभी उत्तर नहीं दिया।"
    for attempt in range(1, GEMINI_MAX_ATTEMPTS + 1):
        for model in _V56_ONLINE_MODELS:
            try:
                ans = _v56_rest_model(question, key, model)
                return ans, "online:" + model
            except Exception as exc:
                last_reason = _v56_gemini_error_text(exc)

        if attempt < GEMINI_MAX_ATTEMPTS:
            print(
                f"⏳ Gemini कोशिश {attempt}/{GEMINI_MAX_ATTEMPTS} असफल — "
                f"{GEMINI_RETRY_DELAY_SECONDS} सेकंड बाद फिर कोशिश..."
            )
            time.sleep(GEMINI_RETRY_DELAY_SECONDS)

    return None, "online_error:" + last_reason


# ---- Safe Pydroid voice ----
def speak(text):
    spoken = str(text).strip()
    if not spoken:
        return False

    # Pydroid terminal mode can import Plyer but fail because no Android JNIEnv exists.
    # Therefore do NOT call plyer_tts here.

    if ANDROID_DROID is not None:
        try:
            ANDROID_DROID.ttsSpeak(spoken)
            return True
        except Exception:
            pass

    # pyttsx3 is optional and often unavailable on Android; if it works, use it.
    if pyttsx3 is not None:
        try:
            engine = pyttsx3.init()
            engine.say(spoken)
            engine.runAndWait()
            engine.stop()
            return True
        except Exception:
            pass

    # Last safe option: a Termux TTS command, if the device has it.
    try:
        import shutil as _v56_shutil, subprocess as _v56_subprocess
        cmd = _v56_shutil.which("termux-tts-speak")
        if cmd:
            _v56_subprocess.run([cmd, spoken], timeout=15, check=False,
                                stdout=_v56_subprocess.DEVNULL,
                                stderr=_v56_subprocess.DEVNULL)
            return True
    except Exception:
        pass

    return False


def _voice_status_line():
    routes = []
    if ANDROID_DROID is not None:
        routes.append("Android TTS")
    if pyttsx3 is not None:
        routes.append("pyttsx3")
    try:
        import shutil as _v56_shutil
        if _v56_shutil.which("termux-tts-speak"):
            routes.append("Termux TTS")
    except Exception:
        pass
    if routes:
        return "🔊 Voice routes: " + ", ".join(routes)
    return "🔇 Pydroid में usable TTS route अभी detect नहीं हुआ; text answer फिर भी चलेगा।"


